<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import Icon from './Icon.vue';
import { state, mutate, resetDemo } from './store';
import * as D from './domain';
import type { Customer, Lead, Member, Opportunity, Role, Stage, State, Tenant } from './domain';

type View = 'dashboard' | 'customers' | 'leads' | 'opportunities' | 'tasks' | 'reports' | 'team' | 'billing' | 'settings' | 'tenants' | 'plans' | 'requests' | 'audits' | 'guide';
type DialogType = '' | 'customer' | 'editCustomer' | 'lead' | 'opportunity' | 'task' | 'convert' | 'stage' | 'activity' | 'transfer' | 'share' | 'member' | 'tenant' | 'renew' | 'requestRenew' | 'plan' | 'reset';
const ctx = reactive<D.Context>({ tenantId: state.tenants[0].id, memberId: state.members.find(m => m.tenantId === state.tenants[0].id && m.active)!.id });
const screen = ref<'tenant' | 'platform' | 'welcome'>('tenant');
const view = ref<View>('dashboard');
const mobileMenu = ref(false), globalSearch = ref(''), search = ref(''), industryFilter = ref(''), levelFilter = ref(''), leadFilter = ref(''), taskFilter = ref('pending');
const boardMode = ref<'board' | 'table' | 'closed'>('board'), selectedCustomers = ref<string[]>([]), selectedCustomerId = ref(''), customerTab = ref('overview');
const draggedOpportunity = ref(''), toast = reactive({ text: '', kind: 'success' }), toastTimer = ref<ReturnType<typeof setTimeout>>();
const dialog = reactive({ type: '' as DialogType, id: '', version: 0, error: '' });
const modalRef = ref<HTMLElement | null>(null); let priorFocus: HTMLElement | null = null;
const form = reactive({ name: '', title: '', industry: '智能装备', level: 'B', source: '官网咨询', region: '', ownerId: '', creditCode: '', description: '', contactName: '', contactPhone: '', contactPosition: '', company: '', contact: '', phone: '', summary: '', customerId: '', amount: '0.00', actualAmount: '', closeDate: '', nextAction: '', reason: '', stage: '需求确认' as Stage, assigneeId: '', dueDate: '', priority: '中' as D.Task['priority'], existingCustomerId: '', createOpportunity: true, content: '', activityType: '电话沟通', memberId: '', email: '', role: 'sales' as Role, department: '销售部', planId: 'basic', adminName: '', months: 3, price: '', seats: 10, storageGB: 5, customerLimit: 1000 });
const tenant = computed(() => state.tenants.find(t => t.id === ctx.tenantId)!);
const member = computed(() => state.members.find(m => m.id === ctx.memberId && m.tenantId === ctx.tenantId)!);
const members = computed(() => state.members.filter(m => m.tenantId === ctx.tenantId && m.active));
const owners = computed(() => members.value.filter(m => m.role !== 'viewer' && (member.value.role !== 'sales' || m.id === member.value.id)));
const plan = computed(() => state.plans.find(p => p.id === tenant.value.planId)!);
const readonly = computed(() => D.subscriptionState(tenant.value) !== '正常' || member.value.role === 'viewer');
const manage = computed(() => ['admin', 'manager'].includes(member.value.role));
const customers = computed(() => D.visibleCustomers(state, ctx));
const leads = computed(() => D.visibleLeads(state, ctx));
const opportunities = computed(() => D.visibleOpportunities(state, ctx));
const tasks = computed(() => D.visibleTasks(state, ctx));
const summary = computed(() => D.totals(state, ctx));
const industries = computed(() => [...new Set(customers.value.map(c => c.industry))]);
const filteredCustomers = computed(() => customers.value.filter(c => (!search.value || (c.name + c.region + ownerName(c.ownerId)).toLowerCase().includes(search.value.toLowerCase())) && (!industryFilter.value || c.industry === industryFilter.value) && (!levelFilter.value || c.level === levelFilter.value)));
const filteredLeads = computed(() => leads.value.filter(l => (!search.value || (l.title + l.company + l.contact).includes(search.value)) && (!leadFilter.value || l.status === leadFilter.value)));
const filteredOpportunities = computed(() => opportunities.value.filter(o => (!search.value || (o.title + customerName(o.customerId)).includes(search.value)) && (boardMode.value === 'closed' ? ['成交', '丢单'].includes(o.stage) : !['成交', '丢单'].includes(o.stage))));
const openStages = D.stages.slice(0, 5);
const filteredTasks = computed(() => tasks.value.filter(t => taskFilter.value === 'all' || (taskFilter.value === 'done' ? t.done : !t.done)).sort((a, b) => a.dueDate.localeCompare(b.dueDate)));
const upcomingTasks = computed(() => tasks.value.filter(t => !t.done).sort((a, b) => a.dueDate.localeCompare(b.dueDate)).slice(0, 5));
const activities = computed(() => state.activities.filter(a => a.tenantId === ctx.tenantId && customers.value.some(c => c.id === a.customerId)).slice(0, 5));
const selectedCustomer = computed(() => customers.value.find(c => c.id === selectedCustomerId.value));
const customerContacts = computed(() => state.contacts.filter(c => c.tenantId === ctx.tenantId && c.customerId === selectedCustomerId.value));
const customerActivities = computed(() => state.activities.filter(a => a.tenantId === ctx.tenantId && a.customerId === selectedCustomerId.value));
const customerOpportunities = computed(() => opportunities.value.filter(o => o.customerId === selectedCustomerId.value));
const pipeline = computed(() => D.stages.map(stage => ({ stage, count: opportunities.value.filter(o => o.stage === stage).length, cents: opportunities.value.filter(o => o.stage === stage).reduce((s, o) => s + D.cents(o.stage === '成交' ? o.actualAmount : o.amount), 0) })));
const maxPipeline = computed(() => Math.max(...pipeline.value.map(x => x.cents), 1));
const sources = computed(() => [...new Set(leads.value.map(l => l.source))].map(source => ({ source, count: leads.value.filter(l => l.source === source).length })));
const globalResults = computed(() => globalSearch.value.trim() ? [
  ...customers.value.filter(c => c.name.includes(globalSearch.value.trim())).map(c => ({ id: c.id, name: c.name, type: '客户' })),
  ...opportunities.value.filter(o => o.title.includes(globalSearch.value.trim())).map(o => ({ id: o.id, name: o.title, type: '商机' }))
].slice(0, 7) : []);
const platformStats = computed(() => ({ count: state.tenants.length, active: state.tenants.filter(t => D.subscriptionState(t) === '正常').length, seats: state.members.filter(m => m.active).length, mrr: state.tenants.filter(t => D.subscriptionState(t) === '正常').reduce((s, t) => s + D.cents(state.plans.find(p => p.id === t.planId)!.price), 0) }));
const pendingRequests = computed(() => state.renewRequests.filter(r => r.status === '待处理'));
const nav = computed(() => screen.value === 'platform' ? [
  { id: 'tenants', label: '企业与租户', icon: 'building' }, { id: 'plans', label: '套餐管理', icon: 'layers' }, { id: 'requests', label: '续费申请', icon: 'wallet' }, { id: 'audits', label: '操作记录', icon: 'shield' }
] : [
  { id: 'dashboard', label: '工作台', icon: 'grid' }, { id: 'customers', label: '客户中心', icon: 'users' }, { id: 'leads', label: '销售线索', icon: 'target' }, { id: 'opportunities', label: '商机看板', icon: 'board' }, { id: 'tasks', label: '跟进与待办', icon: 'checklist' }, { id: 'reports', label: '数据报表', icon: 'chart' }
]);
const titles: Record<View, string> = { dashboard: '工作台', customers: '客户中心', leads: '销售线索', opportunities: '商机看板', tasks: '跟进与待办', reports: '数据报表', team: '组织与成员', billing: '套餐与订阅', settings: '企业设置', tenants: '企业与租户', plans: '套餐管理', requests: '续费申请', audits: '操作记录', guide: '版本与开发进度' };
const dialogTitles: Record<DialogType, string> = { '': '', customer: '新增客户', editCustomer: '编辑客户', lead: '新增销售线索', opportunity: '新增商机', task: '新增待办', convert: '转换有效线索', stage: '推进商机阶段', activity: '记录客户跟进', transfer: '转交客户', share: '调整客户共享', member: '创建演示成员', tenant: '开通演示企业', renew: '演示续费开通', requestRenew: '提交续费申请', plan: '编辑演示套餐', reset: '重置演示数据' };
const dateLabel = computed(() => new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', month: 'long', day: 'numeric', weekday: 'long' }).format(new Date()));
const greeting = computed(() => { const hour = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Shanghai', hour: 'numeric', hourCycle: 'h23' }).format(new Date())); return hour < 12 ? '上午好' : hour < 18 ? '下午好' : '晚上好'; });
function ownerName(id: string) { return state.members.find(m => m.id === id)?.name ?? '未分配'; }
function customerName(id: string) { return id ? customers.value.find(c => c.id === id)?.name ?? '关联客户未授权' : '独立待办'; }
function money(value: number | string, compact = false) { const number = typeof value === 'string' ? Number(value) : value / 100; return compact && Math.abs(number) >= 10000 ? '¥' + (number / 10000).toFixed(number % 10000 ? 1 : 0) + '万' : '¥' + number.toLocaleString('zh-CN', { maximumFractionDigits: 2 }); }
function dateTime(at: string) { return new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(at)); }
function dueLabel(date: string) { return date < D.dateOnly() ? '已逾期' : date === D.dateOnly() ? '今天' : date === D.offsetDate(1) ? '明天' : date.slice(5).replace('-', '/'); }
function initials(name: string) { return name.slice(-2); }
function notify(text: string, kind = 'success') { if (toastTimer.value) clearTimeout(toastTimer.value); toast.text = text; toast.kind = kind; toastTimer.value = setTimeout(() => { toast.text = ''; }, 3800); }
function run(fn: (s: State) => void, message: string) { try { mutate(fn); notify(message); } catch (error) { notify(error instanceof Error ? error.message : '操作未完成', 'error'); } }
function finishTask(id: string) { run(s => D.completeTask(s, ctx, id), '待办已完成'); }
function advanceLead(id: string) { run(s => D.qualifyLead(s, ctx, id), '线索状态已更新'); }
function stageAmount(stage: Stage) { return filteredOpportunities.value.filter(o => o.stage === stage).reduce((total, o) => total + D.cents(o.amount), 0); }
function navigate(id: View) { view.value = id; search.value = ''; industryFilter.value = ''; levelFilter.value = ''; leadFilter.value = ''; selectedCustomers.value = []; selectedCustomerId.value = ''; mobileMenu.value = false; globalSearch.value = ''; }
function setTenant(id: string) { const m = state.members.find(m => m.tenantId === id && m.role === 'admin' && m.active); if (!m) return notify('当前企业没有可用演示管理员', 'error'); ctx.tenantId = id; ctx.memberId = m.id; screen.value = 'tenant'; navigate('dashboard'); }
function selectMember(id: string) { ctx.memberId = id; selectedCustomerId.value = ''; selectedCustomers.value = []; navigate('dashboard'); }
function switchScreen(target: 'tenant' | 'platform') { screen.value = target; navigate(target === 'platform' ? 'tenants' : 'dashboard'); }
function openCustomer(id: string) { selectedCustomerId.value = id; customerTab.value = 'overview'; }
function selectAll(checked: boolean) { selectedCustomers.value = checked ? filteredCustomers.value.map(c => c.id) : []; }
function toggleCustomer(id: string, checked: boolean) { selectedCustomers.value = checked ? [...new Set([...selectedCustomers.value, id])] : selectedCustomers.value.filter(x => x !== id); }
function openDialog(type: DialogType, id = '') {
  dialog.type = type; dialog.id = id; dialog.error = ''; dialog.version = 0;
  Object.assign(form, { name: '', title: '', industry: '智能装备', level: 'B', source: '官网咨询', region: '', ownerId: member.value.id, creditCode: '', description: '', contactName: '', contactPhone: '', contactPosition: '', company: '', contact: '', phone: '', summary: '', customerId: selectedCustomerId.value || customers.value[0]?.id || '', amount: '0.00', actualAmount: '', closeDate: D.offsetDate(30), nextAction: '', reason: '', stage: '需求确认', assigneeId: member.value.id, dueDate: D.dateOnly(), priority: '中', existingCustomerId: '', createOpportunity: true, content: '', activityType: '电话沟通', memberId: members.value.find(m => m.id !== member.value.id)?.id || '', email: '', role: 'sales', department: '销售部', planId: 'basic', adminName: '', months: 3, price: '', seats: 10, storageGB: 5, customerLimit: 1000 });
  if (['editCustomer', 'transfer', 'share'].includes(type)) {
    const c = customers.value.find(c => c.id === id); if (c) { Object.assign(form, c); dialog.version = c.version; }
  }
  if (type === 'convert') { const l = leads.value.find(l => l.id === id)!; dialog.version = l.version; form.title = l.title; form.company = l.company; const match = customers.value.find(c => c.name.trim() === l.company.trim()); form.existingCustomerId = match?.id || ''; }
  if (type === 'stage') { const o = opportunities.value.find(o => o.id === id)!; dialog.version = o.version; form.stage = openStages[Math.min(openStages.indexOf(o.stage) + 1, 4)] as Stage; form.title = o.title; form.amount = o.amount; form.actualAmount = o.amount; form.nextAction = o.nextAction; }
  if (type === 'activity') form.customerId = id || selectedCustomerId.value;
  if (type === 'plan') { const p = state.plans.find(p => p.id === id)!; Object.assign(form, p); }
}
function closeDialog() { dialog.type = ''; dialog.error = ''; priorFocus?.focus(); }
function saveDialog() {
  try {
    const type = dialog.type; let message = '已保存演示修改';
    mutate(s => {
      if (type === 'customer') D.addCustomer(s, ctx, form);
      else if (type === 'editCustomer') D.updateCustomer(s, ctx, dialog.id, dialog.version, form);
      else if (type === 'lead') D.addLead(s, ctx, { title: form.title, company: form.company, contact: form.contact, phone: form.phone, source: form.source, ownerId: form.ownerId, summary: form.summary });
      else if (type === 'opportunity') D.addOpportunity(s, ctx, form);
      else if (type === 'task') D.addTask(s, ctx, form);
      else if (type === 'convert') { D.convertLead(s, ctx, dialog.id, { ...form, expectedVersion: dialog.version }); message = '线索已转换，客户、联系人及所选商机已建立'; }
      else if (type === 'stage') D.transitionOpportunity(s, ctx, dialog.id, dialog.version, form.stage, form.reason, form.actualAmount, form.nextAction);
      else if (type === 'activity') D.addActivity(s, ctx, form.customerId, form.activityType, form.content);
      else if (type === 'transfer') D.transferCustomer(s, ctx, dialog.id, form.ownerId, form.reason);
      else if (type === 'share') D.shareCustomer(s, ctx, dialog.id, form.memberId);
      else if (type === 'member') { D.addMember(s, ctx, form); message = '演示成员已创建，未发送邀请邮件'; }
      else if (type === 'tenant') { D.addTenant(s, form); message = '演示企业已开通，可从企业选择器进入'; }
      else if (type === 'renew') { D.renewTenant(s, dialog.id, Number(form.months)); message = '演示订阅已延期，未产生真实支付'; }
      else if (type === 'requestRenew') { D.requestRenewal(s, ctx, Number(form.months)); message = '演示续费申请已提交，可在平台后台处理'; }
      else if (type === 'plan') {
        const p = s.plans.find(p => p.id === dialog.id)!; const price = D.amountString(form.price);
        if (!form.name.trim() || ![form.seats, form.storageGB, form.customerLimit].every(v => Number.isInteger(Number(v)) && Number(v) > 0)) throw new Error('请填写套餐名称及正整数额度');
        if (s.tenants.filter(t => t.planId === p.id).some(t => s.members.filter(m => m.tenantId === t.id && m.active).length > Number(form.seats) || s.customers.filter(c => c.tenantId === t.id).length > Number(form.customerLimit))) throw new Error('新的套餐额度不能低于已使用数量');
        Object.assign(p, { name: form.name, price, seats: Number(form.seats), storageGB: Number(form.storageGB), customerLimit: Number(form.customerLimit) }); D.audit(s, null, '编辑演示套餐', p.name);
      }
    });
    if (type === 'reset') { resetDemo(); setTenant(state.tenants[0].id); message = '已恢复初始演示数据'; }
    closeDialog(); notify(message);
  } catch (error) { dialog.error = error instanceof Error ? error.message : '请检查输入后重试'; }
}
function exportCustomers() {
  try { const rows = D.exportCustomerRows(state, ctx, selectedCustomers.value.length ? selectedCustomers.value : undefined); download(D.csvString(rows), '客户清单-演示.csv', 'text/csv;charset=utf-8'); run(s => D.audit(s, ctx, '导出演示客户', String(rows.length - 1) + '条'), '演示客户清单已下载'); }
  catch (e) { notify(e instanceof Error ? e.message : '导出失败', 'error'); }
}
function download(content: string, filename: string, type = 'text/markdown;charset=utf-8') { const url = URL.createObjectURL(new Blob([content], { type })); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
function approveRequest(id: string, approve: boolean) { run(s => { const r = s.renewRequests.find(r => r.id === id)!; if (r.status !== '待处理') throw new Error('申请已处理'); if (approve) D.renewTenant(s, r.tenantId, r.months); r.status = approve ? '已确认' : '已驳回'; D.audit(s, null, approve ? '确认演示续费申请' : '驳回演示续费申请', s.tenants.find(t => t.id === r.tenantId)!.name); }, approve ? '演示续费已确认，企业有效期已更新' : '演示申请已驳回'); }
function toggleTenant(t: Tenant) { run(s => { const target = s.tenants.find(x => x.id === t.id)!; target.status = target.status === 'active' ? 'suspended' : 'active'; D.audit(s, null, target.status === 'active' ? '恢复演示企业' : '暂停演示企业', target.name); }, t.status === 'active' ? '演示企业已暂停，业务进入只读' : '演示企业已恢复'); }
function saveSettings() { run(s => { if (D.requireWrite(s, ctx).role !== 'admin') throw new Error('仅企业管理员可修改企业资料'); const t = s.tenants.find(t => t.id === ctx.tenantId)!; if (!settingsName.value.trim()) throw new Error('企业名称不能为空'); if (s.tenants.some(x => x.id !== t.id && x.name.trim() === settingsName.value.trim())) throw new Error('名称与其他演示企业重复'); t.name = settingsName.value.trim(); t.industry = settingsIndustry.value; t.logo = t.name.slice(0, 1); D.audit(s, ctx, '修改企业资料', t.name); }, '企业资料已更新'); }
const settingsName = ref(tenant.value.name), settingsIndustry = ref(tenant.value.industry);
watch(() => [ctx.tenantId, view.value], () => { settingsName.value = tenant.value.name; settingsIndustry.value = tenant.value.industry; });
watch(() => dialog.type, async (type, previous) => { if (type && !previous) priorFocus = document.activeElement as HTMLElement; if (type) { await nextTick(); modalRef.value?.querySelector<HTMLElement>('input:not([type="checkbox"]), select, textarea, button')?.focus(); } });
function keydown(event: KeyboardEvent) {
  if (event.key === 'Escape') { closeDialog(); selectedCustomerId.value = ''; globalSearch.value = ''; mobileMenu.value = false; }
  if (event.key === 'Tab' && dialog.type && modalRef.value) { const els = [...modalRef.value.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled])')]; const first = els[0], last = els.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } }
}
function dropStage(stage: Stage) { const o = opportunities.value.find(o => o.id === draggedOpportunity.value); if (o && o.stage !== stage && !readonly.value) { openDialog('stage', o.id); form.stage = stage; } draggedOpportunity.value = ''; }
function chooseGlobal(result: { id: string; type: string; name: string }) { if (result.type === '客户') { navigate('customers'); openCustomer(result.id); } else { navigate('opportunities'); search.value = result.name; } globalSearch.value = ''; }
function downloadProgress() { download("# 彬彬 CRM 开发记录 v0.10\n\n共五个大阶段：P0、P1、P2、P3、P4。P1 与 P2 分别分为 A～D。\n\n当前 P2-C / D：批准报价建合同、签订与生效、受控合同变更、分期收款、回款登记、异人到账确认、冲正、更正登记及对账 CSV。真实客户企业端登录选择企业 → 合同管理 / 回款管理 / 收款对账；本地流程演示使用虚构数据。\n\n真实企业入口：https://crm-java-api-crm-test.up.railway.app/?account=owner\n平台运营入口：https://crm-java-api-crm-test.up.railway.app/?account=platform-operator\n\n下一大阶段 P3：服务工单、SLA、知识库、营销与系统集成。正式 SMTP、独立密钥交接、真实客户试点、浏览器操作与性能验收仍待完成。当前云测试不等于正式试运营。\n", 'CRM开发记录-v0.10.md'); }
onMounted(() => document.addEventListener('keydown', keydown));
onUnmounted(() => { document.removeEventListener('keydown', keydown); if (toastTimer.value) clearTimeout(toastTimer.value); });
</script>

<template>
  <div v-if="screen === 'welcome'" class="welcome-page">
    <div class="welcome-top"><a class="brand" href="#" @click.prevent="switchScreen('tenant')"><span class="brand-mark"><Icon name="layers" :size="24" /></span><strong>彬彬 CRM</strong></a><span class="preview-tag">产品交互预览 · v0.14</span></div>
    <div class="welcome-content"><div class="welcome-copy"><span class="eyebrow">把每一次跟进，变成持续的客户关系</span><h1>你的客户经营，<br>从这里开始。</h1><p>连接客户、线索、商机与团队协作。<br>为每一家企业建立清晰、有序的销售工作区。</p><div class="welcome-points"><span><Icon name="building" />独立企业工作区</span><span><Icon name="shield" />分层权限演示</span><span><Icon name="board" />销售流程可追踪</span></div><div class="welcome-note"><Icon name="info" :size="17" />本版提供演示身份，不验证正式账号密码。</div></div>
    <div class="entry-card"><span class="eyebrow">无需登录 · 直接进入</span><h2>选择产品体验入口</h2><p>本预览使用虚构数据，操作仅保存在当前浏览器，不影响真实业务。</p><button v-for="t in state.tenants" :key="t.id" class="workspace-entry" @click="setTenant(t.id)"><span class="company-avatar">{{ t.logo }}</span><span><strong>{{ t.name }}</strong><small>{{ t.industry }} · 客户企业管理员</small></span><Icon name="arrow" /></button><div class="entry-divider"><span>平台方入口</span></div><button class="btn primary full" @click="switchScreen('platform')"><Icon name="shield" />进入 SaaS 平台运营后台</button><small class="muted">企业端用于客户经营，平台端用于企业、套餐和续费管理。</small></div></div>
    <div class="welcome-footer">彬彬 CRM · 企业客户经营平台 <span>源码与开发进度持续迭代</span></div>
  </div>
  <div v-else class="app-shell">
    <button v-if="mobileMenu" class="sidebar-backdrop" aria-label="关闭菜单" @click="mobileMenu = false"></button>
    <aside class="sidebar" :class="{ 'mobile-open': mobileMenu }">
      <a class="brand" href="#" @click.prevent="navigate(screen === 'platform' ? 'tenants' : 'dashboard')"><span class="brand-mark"><Icon name="layers" :size="23" /></span><span><strong>彬彬 CRM</strong><small>让客户关系持续生长</small></span></a>
      <div class="workspace-label"><span class="tiny-dot"></span>{{ screen === 'platform' ? '平台运营工作区' : '企业工作区' }}<span class="mini-label">DEMO</span></div>
      <nav aria-label="主导航"><button v-for="item in nav" :key="item.id" class="nav-item" :class="{ active: view === item.id }" :aria-current="view === item.id ? 'page' : undefined" @click="navigate(item.id as View)"><Icon :name="item.icon" /><span>{{ item.label }}</span><span v-if="item.id === 'tasks' && summary.overdue" class="nav-count">{{ summary.overdue }}</span><span v-if="item.id === 'requests' && pendingRequests.length" class="nav-count">{{ pendingRequests.length }}</span></button></nav>
      <template v-if="screen === 'tenant'"><div class="nav-section-label">企业管理</div><nav aria-label="企业管理"><button class="nav-item" :class="{ active: view === 'team' }" @click="navigate('team')"><Icon name="building" />组织与成员</button><button class="nav-item" :class="{ active: view === 'billing' }" @click="navigate('billing')"><Icon name="wallet" />套餐与订阅</button><button class="nav-item" :class="{ active: view === 'settings' }" @click="navigate('settings')"><Icon name="settings" />企业设置</button></nav></template>
      <div class="sidebar-bottom"><div class="release-card"><div><span class="release-dot"></span>云端交互预览 <span class="mini-label">v0.14</span></div><p>深色科技玻璃工作台 · P4 功能基线。</p><button @click="navigate('guide')">查看开发进度<Icon name="arrow" :size="15" /></button></div><button class="nav-item bottom-item" @click="screen = 'welcome'"><Icon name="logout" :size="18" />切换体验入口</button></div>
    </aside>
    <div class="workspace">
      <header class="topbar">
        <div class="breadcrumb"><button class="icon-button mobile-toggle" aria-label="打开菜单" @click="mobileMenu = !mobileMenu"><Icon name="menu" /></button><span>{{ screen === 'platform' ? '平台运营' : '企业工作区' }}</span><Icon name="chevron" :size="13" /><strong>{{ titles[view] }}</strong></div>
        <div class="topbar-actions">
          <div v-if="screen === 'tenant'" class="global-search"><Icon name="search" :size="17" /><input v-model="globalSearch" aria-label="搜索当前身份可见的客户或商机" placeholder="搜索客户、商机…" /><span class="search-shortcut">搜索</span><div v-if="globalSearch.trim()" class="search-popover"><button v-for="r in globalResults" :key="r.id" @click="chooseGlobal(r)"><span class="badge neutral">{{ r.type }}</span>{{ r.name }}<Icon name="arrow" :size="14" /></button><div v-if="!globalResults.length" class="empty-small">没有当前身份可见的匹配结果</div></div></div>
          <button class="icon-button" :aria-label="screen === 'platform' ? '查看续费申请' : '查看待办提醒'" @click="navigate(screen === 'platform' ? 'requests' : 'tasks')"><Icon name="bell" /><i v-if="screen === 'platform' ? pendingRequests.length : summary.overdue"></i></button>
          <button class="workspace-switch" @click="switchScreen(screen === 'tenant' ? 'platform' : 'tenant')"><Icon :name="screen === 'tenant' ? 'shield' : 'building'" :size="16" /><span>{{ screen === 'tenant' ? '平台演示' : '企业演示' }}</span></button>
          <span class="avatar dark">{{ screen === 'tenant' ? initials(member.name) : '运营' }}</span>
        </div>
      </header>
      <div class="preview-strip"><span><Icon name="info" :size="15" /><strong>在线产品预览</strong> 虚构企业与客户数据，可直接点击菜单、查看、编辑和体验流程。</span><button @click="navigate('guide')">P4 开发进度 ↗</button></div>
      <div v-if="screen === 'tenant'" class="context-bar"><div class="tenant-selector"><span class="company-avatar small">{{ tenant.logo }}</span><label class="visually-hidden" for="tenant-select">选择演示企业</label><select id="tenant-select" :value="ctx.tenantId" @change="setTenant(($event.target as HTMLSelectElement).value)"><option v-for="t in state.tenants" :key="t.id" :value="t.id">{{ t.name }}</option></select><span class="badge green">{{ plan.name }}</span></div><div class="identity-selector"><Icon name="users" :size="16" /><label for="member-select">演示身份</label><select id="member-select" :value="ctx.memberId" @change="selectMember(($event.target as HTMLSelectElement).value)"><option v-for="m in members" :key="m.id" :value="m.id">{{ m.name }} · {{ D.roleLabels[m.role] }}</option></select></div></div>
      <div v-if="screen === 'tenant' && D.subscriptionState(tenant) !== '正常'" class="subscription-banner"><Icon name="lock" :size="18" />{{ D.subscriptionState(tenant) === '只读' ? '当前演示订阅已到期，业务数据进入只读状态。' : '当前演示企业已暂停，业务写入已限制。' }}<button @click="navigate('billing')">查看订阅</button></div>
      <main class="page-content">
        <template v-if="view === 'dashboard'">
          <div class="page-heading"><div><span class="eyebrow">{{ dateLabel }}</span><h1>{{ member.name }}，{{ greeting }}<span class="greeting-dot">。</span></h1><p>让今天的每一次跟进，都有清晰的下一步。</p></div><div class="heading-actions"><button class="btn secondary" :disabled="readonly" @click="openDialog('task')"><Icon name="plus" :size="16" />新增待办</button><button class="btn primary" :disabled="readonly" @click="openDialog('customer')"><Icon name="plus" :size="17" />新增客户</button></div></div>
          <div class="metric-grid"><button class="metric-card" @click="navigate('customers')"><span class="metric-label">客户总数<Icon name="users" /></span><strong>{{ summary.customers }}<small>家</small></strong><span class="metric-foot"><span class="metric-link">查看客户档案</span><Icon name="arrow" :size="15" /></span></button><button class="metric-card" @click="navigate('opportunities')"><span class="metric-label">在途商机金额<Icon name="target" /></span><strong>{{ money(summary.pipelineCents, true) }}</strong><span class="metric-foot"><span>{{ summary.open }} 个在途商机</span><Icon name="arrow" :size="15" /></span></button><button class="metric-card" @click="navigate('leads')"><span class="metric-label">待跟进线索<Icon name="flag" /></span><strong>{{ summary.leads }}<small>条</small></strong><span class="metric-foot"><span>{{ leads.filter(l => l.status === '有效').length }} 条有效线索可转换</span><Icon name="arrow" :size="15" /></span></button><button class="metric-card" @click="navigate('tasks')"><span class="metric-label">待处理事项<Icon name="clock" /></span><strong>{{ tasks.filter(t => !t.done).length }}<small>项</small></strong><span class="metric-foot"><span :class="{ danger: summary.overdue > 0 }">{{ summary.overdue ? summary.overdue + ' 项已逾期' : '当前没有逾期事项' }}</span><Icon name="arrow" :size="15" /></span></button></div>
          <div class="dashboard-grid"><section class="card pipeline-card"><div class="card-heading"><div><h2>销售管道</h2><p>当前在途商机 · 按阶段汇总</p></div><button class="text-button" @click="navigate('opportunities')">查看看板<Icon name="chevron" :size="15" /></button></div><div class="pipeline-total"><strong>{{ money(summary.pipelineCents) }}</strong><span>加权预测 {{ money(summary.weightedCents) }}</span></div><div class="pipeline-bars"><button v-for="(p, i) in pipeline.slice(0, 5)" :key="p.stage" @click="navigate('opportunities')"><span class="bar-label">{{ p.stage }}<small>{{ p.count }} 个</small></span><span class="bar-track"><span class="bar-fill" :class="'shade-' + i" :style="{ width: (p.cents ? Math.max(p.cents / maxPipeline * 100, 5) : 0) + '%' }"></span></span><strong>{{ money(p.cents, true) }}</strong></button></div><div class="chart-note"><span class="tiny-dot"></span>金额为商机预测口径，成交与实收分别统计。</div></section>
          <section class="card task-card"><div class="card-heading"><div><h2>接下来要做</h2><p>按截止日期排序</p></div><button class="text-button" @click="navigate('tasks')">全部<Icon name="chevron" :size="15" /></button></div><div v-for="t in upcomingTasks" :key="t.id" class="compact-task"><button class="task-check" :disabled="readonly" :aria-label="'完成待办：' + t.title" @click="finishTask(t.id)"><Icon name="check" :size="14" /></button><div class="compact-task-copy"><strong>{{ t.title }}</strong><span>{{ customerName(t.customerId) }} · {{ ownerName(t.assigneeId) }}</span></div><span class="badge" :class="t.dueDate < D.dateOnly() ? 'red' : t.dueDate === D.dateOnly() ? 'amber' : 'neutral'">{{ dueLabel(t.dueDate) }}</span></div><div v-if="!upcomingTasks.length" class="empty-state small"><Icon name="checklist" :size="30" /><strong>待办全部完成</strong><p>可以新增下一次跟进计划。</p></div><button class="card-bottom-action" :disabled="readonly" @click="openDialog('task')"><Icon name="plus" :size="15" />添加下一步</button></section>
          <section class="card focus-card"><div class="card-heading"><div><h2>重点商机</h2><p>近期预计成交的业务</p></div><button class="text-button" @click="navigate('opportunities')">全部商机<Icon name="chevron" :size="15" /></button></div><div class="table-scroll"><table><thead><tr><th>商机 / 客户</th><th>当前阶段</th><th>预计金额</th><th>预计成交</th><th></th></tr></thead><tbody><tr v-for="o in opportunities.filter(o => !['成交', '丢单'].includes(o.stage)).sort((a, b) => a.closeDate.localeCompare(b.closeDate)).slice(0, 4)" :key="o.id"><td><button class="table-name" @click="openCustomer(o.customerId)">{{ o.title }}</button><small class="cell-sub">{{ customerName(o.customerId) }}</small></td><td><span class="badge green">{{ o.stage }}</span></td><td class="numeric">{{ money(o.amount) }}</td><td>{{ o.closeDate.slice(5) }}</td><td><button class="icon-button" aria-label="推进商机阶段" :disabled="readonly" @click="openDialog('stage', o.id)"><Icon name="arrow" :size="16" /></button></td></tr><tr v-if="!opportunities.filter(o => !['成交', '丢单'].includes(o.stage)).length"><td colspan="5" class="empty-cell">还没有在途商机，可以从有效线索开始。</td></tr></tbody></table></div></section>
          <section class="card activity-card"><div class="card-heading"><div><h2>最近跟进</h2><p>客户关系的每一步都有记录</p></div><Icon name="note" :size="18" /></div><div class="activity-timeline"><div v-for="a in activities" :key="a.id" class="timeline-item"><span class="timeline-dot"></span><div><button @click="openCustomer(a.customerId)">{{ customerName(a.customerId) }}</button><p>{{ a.content }}</p><small>{{ ownerName(a.actorId) }} · {{ a.type }} · {{ dateTime(a.at) }}</small></div></div><div v-if="!activities.length" class="empty-small">还没有当前身份可见的跟进记录。</div></div></section></div>
        </template>

        <template v-else-if="view === 'customers'">
          <div class="page-heading"><div><span class="eyebrow">CUSTOMER RELATIONSHIPS</span><h1>客户中心<span class="heading-count">{{ customers.length }}</span></h1><p>建立完整客户档案，让关系与机会沉淀在一起。</p></div><div class="heading-actions"><button v-if="manage" class="btn secondary" @click="exportCustomers"><Icon name="download" :size="16" />导出{{ selectedCustomers.length ? '所选' : '客户' }}</button><button class="btn primary" :disabled="readonly" @click="openDialog('customer')"><Icon name="plus" :size="17" />新增客户</button></div></div>
          <section class="card data-card"><div class="table-toolbar"><div class="segment-tabs"><button :class="{ active: !levelFilter }" @click="levelFilter = ''">全部客户</button><button v-for="l in ['A', 'B', 'C']" :key="l" :class="{ active: levelFilter === l }" @click="levelFilter = l">{{ l }} 级客户</button></div><div class="table-filters"><div class="input-search"><Icon name="search" :size="16" /><input v-model="search" aria-label="筛选客户" placeholder="名称、地区、负责人" /></div><select v-model="industryFilter" aria-label="按行业筛选"><option value="">全部行业</option><option v-for="i in industries" :key="i">{{ i }}</option></select></div></div><div class="table-scroll"><table class="customer-table"><thead><tr><th class="checkbox-cell"><input type="checkbox" aria-label="全选当前客户" :checked="filteredCustomers.length > 0 && filteredCustomers.every(c => selectedCustomers.includes(c.id))" @change="selectAll(($event.target as HTMLInputElement).checked)" /></th><th>客户名称</th><th>行业 / 地区</th><th>等级</th><th>负责人</th><th>最近跟进</th><th>操作</th></tr></thead><tbody><tr v-for="(c, i) in filteredCustomers" :key="c.id"><td><input type="checkbox" :aria-label="'选择 ' + c.name" :checked="selectedCustomers.includes(c.id)" @change="toggleCustomer(c.id, ($event.target as HTMLInputElement).checked)" /></td><td><div class="customer-cell"><span class="company-avatar" :class="'color-' + i % 5">{{ c.name.slice(0, 1) }}</span><div><button class="table-name" @click="openCustomer(c.id)">{{ c.name }}</button><small class="cell-sub">{{ c.source }}<span v-if="c.shares.length"> · 已共享</span></small></div></div></td><td>{{ c.industry }}<small class="cell-sub">{{ c.region || '地区待补充' }}</small></td><td><span class="level-badge" :class="'level-' + c.level">{{ c.level }}</span></td><td><div class="owner-cell"><span class="avatar small" :class="c.ownerId === 'm-wang' ? 'teal' : 'purple'">{{ initials(ownerName(c.ownerId)) }}</span>{{ ownerName(c.ownerId) }}</div></td><td><span v-if="state.activities.find(a => a.customerId === c.id)">{{ dateTime(state.activities.find(a => a.customerId === c.id)!.at) }}</span><span v-else class="muted">待首次跟进</span></td><td><button class="text-button" @click="openCustomer(c.id)">查看<Icon name="chevron" :size="13" /></button></td></tr><tr v-if="!filteredCustomers.length"><td colspan="7" class="empty-cell"><Icon name="users" :size="28" /><strong>没有符合条件的客户</strong><span>调整筛选条件，或新增第一个客户。</span></td></tr></tbody></table></div><div class="table-footer"><span>共 {{ filteredCustomers.length }} 家可见客户<span v-if="selectedCustomers.length">，已选 {{ selectedCustomers.length }} 家</span></span><span>仅展示当前演示身份可访问的资料</span></div></section>
        </template>

        <template v-else-if="view === 'leads'">
          <div class="page-heading"><div><span class="eyebrow">FROM INTEREST TO OPPORTUNITY</span><h1>销售线索</h1><p>先确认需求，再把有效线索转化为客户与商机。</p></div><button class="btn primary" :disabled="readonly" @click="openDialog('lead')"><Icon name="plus" :size="17" />新增线索</button></div>
          <div class="stat-ribbon"><button v-for="s in ['新建', '跟进中', '有效', '已转换']" :key="s" :class="{ active: leadFilter === s }" @click="leadFilter = leadFilter === s ? '' : s"><span>{{ s }}</span><strong>{{ leads.filter(l => l.status === s).length }}</strong></button></div>
          <section class="card data-card"><div class="table-toolbar"><h2>线索列表 <span class="muted">{{ filteredLeads.length }}</span></h2><div class="table-filters"><div class="input-search"><Icon name="search" :size="16" /><input v-model="search" aria-label="搜索线索" placeholder="线索、企业、联系人" /></div><select v-model="leadFilter" aria-label="按线索状态筛选"><option value="">全部状态</option><option v-for="s in ['新建', '跟进中', '有效', '已转换', '无效']" :key="s">{{ s }}</option></select></div></div><div class="table-scroll"><table><thead><tr><th>线索 / 企业</th><th>联系人</th><th>来源</th><th>负责人</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="l in filteredLeads" :key="l.id"><td><strong class="record-title">{{ l.title }}</strong><small class="cell-sub">{{ l.company }}</small></td><td>{{ l.contact }}<small class="cell-sub">{{ D.maskPhone(l.phone, member.role) }}</small></td><td><span class="badge neutral">{{ l.source }}</span></td><td>{{ ownerName(l.ownerId) }}</td><td><span class="badge" :class="l.status === '有效' || l.status === '已转换' ? 'green' : l.status === '跟进中' ? 'blue' : 'neutral'">{{ l.status }}</span></td><td><button v-if="l.status === '有效'" class="btn small primary-light" :disabled="readonly" @click="openDialog('convert', l.id)">转换商机<Icon name="arrow" :size="13" /></button><button v-else-if="l.status === '新建' || l.status === '跟进中'" class="text-button" :disabled="readonly" @click="advanceLead(l.id)">{{ l.status === '新建' ? '开始跟进' : '判定有效' }}<Icon name="chevron" :size="13" /></button><button v-else-if="l.conversion" class="text-button" @click="openCustomer(l.conversion.customerId)">查看客户<Icon name="chevron" :size="13" /></button></td></tr><tr v-if="!filteredLeads.length"><td colspan="6" class="empty-cell">当前没有符合条件的线索。</td></tr></tbody></table></div><div class="table-footer"><span>有效线索可选择关联已有客户，并选择是否创建商机。</span><span>全部数据均为演示</span></div></section>
        </template>

        <template v-else-if="view === 'opportunities'">
          <div class="page-heading"><div><span class="eyebrow">A CLEAR PATH TO EVERY DEAL</span><h1>商机看板</h1><p>每个阶段有明确的下一步，每次推进留下记录。</p></div><button class="btn primary" :disabled="readonly" @click="openDialog('opportunity')"><Icon name="plus" :size="17" />新增商机</button></div><div class="opportunity-toolbar"><div class="segment-control"><button :class="{ active: boardMode === 'board' }" @click="boardMode = 'board'"><Icon name="board" :size="15" />阶段看板</button><button :class="{ active: boardMode === 'table' }" @click="boardMode = 'table'"><Icon name="checklist" :size="15" />在途列表</button><button :class="{ active: boardMode === 'closed' }" @click="boardMode = 'closed'">已关闭</button></div><div class="input-search"><Icon name="search" :size="16" /><input v-model="search" aria-label="筛选商机" placeholder="搜索商机或客户" /></div><span class="muted">{{ filteredOpportunities.length }} 个商机 · 拖动卡片可发起阶段变更</span></div>
          <div v-if="boardMode === 'board'" class="kanban"><section v-for="(stage, i) in openStages" :key="stage" class="kanban-column" @dragover.prevent @drop.prevent="dropStage(stage)"><div class="kanban-heading"><span class="stage-dot" :class="'shade-' + i"></span><strong>{{ stage }}</strong><span class="kanban-count">{{ filteredOpportunities.filter(o => o.stage === stage).length }}</span><small>{{ D.probabilities[stage] }}%</small></div><div class="kanban-amount">{{ money(stageAmount(stage), true) }}</div><article v-for="o in filteredOpportunities.filter(o => o.stage === stage)" :key="o.id" class="deal-card" :draggable="!readonly" @dragstart="draggedOpportunity = o.id"><button class="deal-title" @click="openCustomer(o.customerId)">{{ o.title }}</button><p>{{ customerName(o.customerId) }}</p><strong class="deal-value">{{ money(o.amount) }}</strong><div class="deal-next"><Icon name="arrow" :size="14" /><span>{{ o.nextAction }}</span></div><div class="deal-footer"><span class="avatar small teal" :title="ownerName(o.ownerId)">{{ initials(ownerName(o.ownerId)) }}</span><span><Icon name="calendar" :size="13" />{{ o.closeDate.slice(5) }}</span><button class="icon-button" :disabled="readonly" :aria-label="'推进 ' + o.title" @click="openDialog('stage', o.id)"><Icon name="arrow" :size="16" /></button></div></article><div v-if="!filteredOpportunities.some(o => o.stage === stage)" class="kanban-empty">此阶段暂无商机</div><button class="kanban-add" :disabled="readonly" @click="openDialog('opportunity')"><Icon name="plus" :size="14" />添加商机</button></section></div>
          <section v-else class="card data-card"><div class="table-scroll"><table><thead><tr><th>商机</th><th>客户</th><th>阶段</th><th>{{ boardMode === 'closed' ? '成交 / 预计金额' : '预计金额' }}</th><th>负责人</th><th>预计成交</th><th>操作</th></tr></thead><tbody><tr v-for="o in filteredOpportunities" :key="o.id"><td><strong class="record-title">{{ o.title }}</strong><small class="cell-sub">{{ boardMode === 'closed' ? o.reason || '已登记成交事实' : o.nextAction }}</small></td><td><button class="table-name" @click="openCustomer(o.customerId)">{{ customerName(o.customerId) }}</button></td><td><span class="badge" :class="o.stage === '丢单' ? 'red' : 'green'">{{ o.stage }}</span></td><td class="numeric">{{ money(o.stage === '成交' ? o.actualAmount : o.amount) }}</td><td>{{ ownerName(o.ownerId) }}</td><td>{{ o.closeDate }}</td><td><button v-if="boardMode !== 'closed'" class="text-button" :disabled="readonly" @click="openDialog('stage', o.id)">推进阶段</button><span v-else class="muted">历史已保留</span></td></tr><tr v-if="!filteredOpportunities.length"><td colspan="7" class="empty-cell">暂无符合条件的商机。</td></tr></tbody></table></div></section>
        </template>

        <template v-else-if="view === 'tasks'">
          <div class="page-heading"><div><span class="eyebrow">MAKE THE NEXT STEP HAPPEN</span><h1>跟进与待办</h1><p>把沟通后的下一步安排好，重要事项不遗漏。</p></div><button class="btn primary" :disabled="readonly" @click="openDialog('task')"><Icon name="plus" :size="17" />新增待办</button></div><section class="card data-card"><div class="table-toolbar"><div class="segment-tabs"><button :class="{ active: taskFilter === 'pending' }" @click="taskFilter = 'pending'">待处理 <span>{{ tasks.filter(t => !t.done).length }}</span></button><button :class="{ active: taskFilter === 'done' }" @click="taskFilter = 'done'">已完成 <span>{{ tasks.filter(t => t.done).length }}</span></button><button :class="{ active: taskFilter === 'all' }" @click="taskFilter = 'all'">全部</button></div><span class="muted">{{ summary.overdue }} 项逾期</span></div><div v-for="t in filteredTasks" :key="t.id" class="task-list-row"><button class="task-check" :class="{ checked: t.done }" :disabled="readonly || t.done" :aria-label="'完成 ' + t.title" @click="finishTask(t.id)"><Icon name="check" :size="15" /></button><div class="task-list-copy"><strong :class="{ completed: t.done }">{{ t.title }}</strong><small><button v-if="t.customerId && customers.some(c => c.id === t.customerId)" @click="openCustomer(t.customerId)">{{ customerName(t.customerId) }}</button><span v-else>独立待办</span><span> · {{ ownerName(t.assigneeId) }}</span></small></div><span class="priority-dot" :class="'priority-' + t.priority">{{ t.priority }}优先级</span><span class="badge" :class="t.done ? 'green' : t.dueDate < D.dateOnly() ? 'red' : 'neutral'">{{ t.done ? '已完成' : dueLabel(t.dueDate) }}</span><span class="task-date">{{ t.dueDate }}</span></div><div v-if="!filteredTasks.length" class="empty-state"><Icon name="checklist" :size="40" /><h3>{{ taskFilter === 'done' ? '还没有已完成待办' : '当前没有待处理事项' }}</h3><p>可以从客户详情中记录跟进，或创建下一次联系计划。</p></div></section>
        </template>

        <template v-else-if="view === 'reports'">
          <div class="page-heading"><div><span class="eyebrow">SEE THE BUSINESS CLEARLY</span><h1>数据报表</h1><p>统计与明细使用同一演示权限范围，可直接核对。</p></div><span class="badge green">当前数据快照</span></div><div class="metric-grid"><div class="metric-card"><span class="metric-label">在途商机金额<Icon name="target" /></span><strong>{{ money(summary.pipelineCents, true) }}</strong><span class="metric-foot">排除成交与丢单</span></div><div class="metric-card"><span class="metric-label">加权预测<Icon name="chart" /></span><strong>{{ money(summary.weightedCents, true) }}</strong><span class="metric-foot">金额 × 阶段默认概率</span></div><div class="metric-card"><span class="metric-label">累计成交金额<Icon name="check" /></span><strong>{{ money(summary.wonCents, true) }}</strong><span class="metric-foot">商机成交口径，非实收</span></div><div class="metric-card"><span class="metric-label">已关闭商机成交率<Icon name="flag" /></span><strong>{{ summary.winRate === null ? '—' : summary.winRate + '%' }}</strong><span class="metric-foot">成交数 ÷ 已关闭商机数</span></div></div><div class="two-column"><section class="card"><div class="card-heading"><div><h2>商机阶段分布</h2><p>当前阶段，包含已关闭商机</p></div></div><div class="report-bars"><button v-for="(p, i) in pipeline" :key="p.stage" @click="navigate('opportunities'); boardMode = ['成交', '丢单'].includes(p.stage) ? 'closed' : 'table'"><span>{{ p.stage }}</span><span class="bar-track"><span class="bar-fill" :class="'shade-' + Math.min(i, 4)" :style="{ width: (p.cents ? Math.max(p.cents / maxPipeline * 100, 3) : 0) + '%' }"></span></span><strong>{{ p.count }} 个</strong><small>{{ money(p.cents, true) }}</small></button></div></section><section class="card"><div class="card-heading"><div><h2>线索来源</h2><p>来源登记统计，非营销归因</p></div></div><div class="source-list"><button v-for="(s, i) in sources" :key="s.source" @click="navigate('leads')"><span class="source-icon" :class="'color-' + i % 5"><Icon :name="['link', 'flag', 'users', 'target'][i % 4]" :size="18" /></span><strong>{{ s.source }}</strong><span class="source-bar"><i :style="{ width: s.count / Math.max(leads.length, 1) * 100 + '%' }"></i></span><span>{{ s.count }} 条</span></button><div v-if="!sources.length" class="empty-small">没有可统计的线索。</div></div><div class="chart-note">历史转化率、渠道成本和目标预测将在后续迭代提供。</div></section></div>
        </template>

        <template v-else-if="view === 'team'">
          <div class="page-heading"><div><span class="eyebrow">GROW WITH YOUR TEAM</span><h1>组织与成员</h1><p>每位成员有明确的角色、归属和访问范围。</p></div><button v-if="member.role === 'admin'" class="btn primary" :disabled="readonly" @click="openDialog('member')"><Icon name="plus" :size="17" />创建演示成员</button></div><div class="info-banner"><Icon name="shield" /><div><strong>{{ members.length }} / {{ plan.seats }} 个成员名额</strong><span>销售仅看本人负责或获共享的客户；企业管理员和经理查看当前企业范围。此处为前端权限演示。</span></div></div><section class="card data-card"><div class="table-scroll"><table><thead><tr><th>成员</th><th>邮箱</th><th>部门</th><th>角色</th><th>状态</th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td><div class="owner-cell"><span class="avatar teal">{{ initials(m.name) }}</span><strong>{{ m.name }}</strong><span v-if="m.id === member.id" class="badge neutral">当前演示</span></div></td><td>{{ m.email }}</td><td>{{ m.department }}</td><td><span class="badge" :class="m.role === 'admin' ? 'green' : m.role === 'manager' ? 'blue' : 'neutral'">{{ D.roleLabels[m.role] }}</span></td><td><span class="status-dot"></span>有效</td></tr></tbody></table><div class="roadmap-step"><span>07</span><div><strong>P2-B · 报价审批</strong><p>指定经理、异人审批、版本锁定与重新审批已实现。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>08</span><div><strong>P2-C / D · 合同与回款</strong><p>批准报价建合同、受控变更、分期收款、到账确认、冲正、更正登记与对账已接入。真实入口：合同管理 / 回款管理 / 收款对账。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>09</span><div><strong>P3 · 客户服务与系统集成</strong><p>服务工单、SLA、知识库、营销与系统集成。</p></div><span class="badge neutral">待开发</span></div><div class="roadmap-step"><span>10</span><div><strong>P4 · 行业配置、客户门户与 AI</strong><p>行业配置、客户门户与 AI 辅助。</p></div><span class="badge neutral">待开发</span></div></div></section><div class="inline-note"><Icon name="info" :size="16" />本版创建成员不会发出邀请邮件，也不会生成正式登录账号。</div>
        </template>

        <template v-else-if="view === 'billing'">
          <div class="page-heading"><div><span class="eyebrow">YOUR WORKSPACE SUBSCRIPTION</span><h1>套餐与订阅</h1><p>功能、成员名额和有效期集中管理。</p></div><span class="badge" :class="D.subscriptionState(tenant) === '正常' ? 'green' : 'amber'">{{ D.subscriptionState(tenant) }}</span></div><section class="subscription-card"><div><span class="eyebrow">当前演示套餐</span><h2>{{ plan.name }}<span>{{ money(plan.price) }} / 月</span></h2><p>{{ plan.description }}</p><div class="subscription-meta"><span>到期日期 <strong>{{ tenant.expiresAt }}</strong></span><span>成员名额 <strong>{{ members.length }} / {{ plan.seats }}</strong></span><span>客户数量 <strong>{{ customers.length }} / {{ plan.customerLimit }}</strong></span></div></div><button v-if="member.role === 'admin'" class="btn primary" @click="openDialog('requestRenew')"><Icon name="wallet" :size="17" />申请演示续费</button></section><div class="two-column"><section class="card"><div class="card-heading"><h2>套餐包含</h2></div><ul class="feature-list"><li v-for="feature in plan.modules" :key="feature"><Icon name="check" :size="17" />{{ feature }}</li></ul><div class="chart-note">标注“后续”的模块尚未实现，套餐价格仅为演示。</div></section><section class="card"><div class="card-heading"><h2>附件容量</h2></div><div class="storage-card"><Icon name="layers" :size="34" /><strong>{{ tenant.storageUsedMB }} MB <small>/ {{ plan.storageGB }} GB</small></strong><div class="bar-track"><span class="bar-fill shade-0" :style="{ width: tenant.storageUsedMB / (plan.storageGB * 1024) * 100 + '%' }"></span></div><p>当前容量值为示例。文件上传与云存储将在正式服务中接入。</p></div></section></div><section class="card"><div class="card-heading"><h2>本企业续费申请</h2></div><div class="table-scroll"><table><thead><tr><th>申请时间</th><th>续费周期</th><th>处理状态</th></tr></thead><tbody><tr v-for="r in state.renewRequests.filter(r => r.tenantId === ctx.tenantId)" :key="r.id"><td>{{ dateTime(r.at) }}</td><td>{{ r.months }} 个月</td><td><span class="badge" :class="r.status === '已确认' ? 'green' : 'amber'">{{ r.status }}</span></td></tr><tr v-if="!state.renewRequests.some(r => r.tenantId === ctx.tenantId)"><td colspan="3" class="empty-cell">暂无续费申请。提交后可在平台演示后台处理。</td></tr></tbody></table></div></section>
        </template>

        <template v-else-if="view === 'settings'">
          <div class="page-heading"><div><span class="eyebrow">WORKSPACE PREFERENCES</span><h1>企业设置</h1><p>维护企业资料，查看演示版数据和使用边界。</p></div></div><div class="two-column"><section class="card settings-card"><div class="card-heading"><h2>企业资料</h2></div><form @submit.prevent="saveSettings"><label>企业名称<input v-model="settingsName" maxlength="100" :disabled="readonly || member.role !== 'admin'" required /></label><label>所属行业<input v-model="settingsIndustry" :disabled="readonly || member.role !== 'admin'" /></label><label>业务时区<input value="Asia/Shanghai（北京时间）" disabled /></label><button v-if="member.role === 'admin'" class="btn primary" :disabled="readonly">保存企业资料</button></form></section><section class="card settings-card"><div class="card-heading"><h2>演示数据管理</h2></div><div class="settings-info"><Icon name="info" :size="24" /><strong>仅用于产品预览</strong><p>修改保存在当前浏览器。不同浏览器、设备之间不共享。请使用虚构内容体验，真实服务已接入 Java＋PostgreSQL，请通过“打开真实服务测试版”使用云端工作区。</p><button class="btn secondary" @click="openDialog('reset')"><Icon name="refresh" :size="16" />恢复初始演示数据</button><button class="text-button" @click="navigate('guide')">查看下一阶段开发内容<Icon name="arrow" :size="14" /></button></div></section></div>
        </template>

        <template v-else-if="view === 'tenants'">
          <div class="page-heading"><div><span class="eyebrow">SAAS OPERATIONS</span><h1>企业与租户</h1><p>管理企业开通、订阅与用量。此工作区不展示企业客户正文。</p></div><button class="btn primary" @click="openDialog('tenant')"><Icon name="plus" :size="17" />开通演示企业</button></div><div class="metric-grid"><div class="metric-card"><span class="metric-label">企业总数<Icon name="building" /></span><strong>{{ platformStats.count }}<small>家</small></strong><span class="metric-foot">当前浏览器演示数据</span></div><div class="metric-card"><span class="metric-label">有效订阅<Icon name="check" /></span><strong>{{ platformStats.active }}<small>家</small></strong><span class="metric-foot">状态正常且在有效期内</span></div><div class="metric-card"><span class="metric-label">演示月度订阅额<Icon name="wallet" /></span><strong>{{ money(platformStats.mrr) }}</strong><span class="metric-foot">按示例套餐汇总，非实际收入</span></div><div class="metric-card"><span class="metric-label">有效成员<Icon name="users" /></span><strong>{{ platformStats.seats }}<small>人</small></strong><span class="metric-foot">各企业成员数汇总</span></div></div><section class="card data-card"><div class="table-toolbar"><h2>企业清单</h2><span class="badge neutral">示例数据</span></div><div class="table-scroll"><table><thead><tr><th>企业</th><th>套餐</th><th>成员名额</th><th>到期时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="(t, i) in state.tenants" :key="t.id"><td><div class="customer-cell"><span class="company-avatar" :class="'color-' + i % 5">{{ t.logo }}</span><div><strong>{{ t.name }}</strong><small class="cell-sub">{{ t.industry }} · 管理员 {{ t.adminName }}</small></div></div></td><td><span class="badge green">{{ state.plans.find(p => p.id === t.planId)?.name }}</span></td><td>{{ state.members.filter(m => m.tenantId === t.id && m.active).length }} / {{ state.plans.find(p => p.id === t.planId)?.seats }}</td><td>{{ t.expiresAt }}</td><td><span class="badge" :class="D.subscriptionState(t) === '正常' ? 'green' : 'amber'">{{ D.subscriptionState(t) }}</span></td><td><div class="row-actions"><button class="text-button" @click="setTenant(t.id)">体验工作区</button><button class="text-button" @click="openDialog('renew', t.id)">演示续费</button><button class="text-button subtle" @click="toggleTenant(t)">{{ t.status === 'active' ? '暂停' : '恢复' }}</button></div></td></tr></tbody></table></div><div class="table-footer"><span>“体验工作区”切换到示例管理员身份；正式运营访问将采用单独授权。</span></div></section>
        </template>

        <template v-else-if="view === 'plans'">
          <div class="page-heading"><div><span class="eyebrow">PLANS & ENTITLEMENTS</span><h1>套餐管理</h1><p>演示价格与额度配置，最终售价待商业验证后确定。</p></div><span class="badge amber">价格仅作演示</span></div><div class="plan-grid"><section v-for="p in state.plans" :key="p.id" class="plan-card" :class="{ featured: p.id === 'professional' }"><span v-if="p.id === 'professional'" class="plan-ribbon">团队协作</span><span class="eyebrow">{{ p.id.toUpperCase() }}</span><h2>{{ p.name }}</h2><p>{{ p.description }}</p><div class="plan-price">{{ money(p.price) }}<small>/ 月</small></div><div class="plan-quotas"><span><Icon name="users" :size="17" />{{ p.seats }} 个成员名额</span><span><Icon name="building" :size="17" />{{ p.customerLimit.toLocaleString() }} 家客户</span><span><Icon name="layers" :size="17" />{{ p.storageGB }} GB 附件容量</span></div><ul class="feature-list"><li v-for="feature in p.modules" :key="feature"><Icon name="check" :size="16" />{{ feature }}</li></ul><button class="btn full" :class="p.id === 'professional' ? 'primary' : 'secondary'" @click="openDialog('plan', p.id)">编辑演示套餐</button></section></div><div class="inline-note"><Icon name="info" :size="16" />成员与客户额度在演示规则中生效；附件容量、后续模块和支付尚未接入真实服务。</div>
        </template>

        <template v-else-if="view === 'requests'">
          <div class="page-heading"><div><span class="eyebrow">SUBSCRIPTION REQUESTS</span><h1>续费申请</h1><p>演示企业提交申请、运营人员确认、有效期更新的流程。</p></div><span class="badge amber">{{ pendingRequests.length }} 项待处理</span></div><section class="card data-card"><div class="table-scroll"><table><thead><tr><th>企业</th><th>申请时间</th><th>续费周期</th><th>状态</th><th>处理</th></tr></thead><tbody><tr v-for="r in state.renewRequests" :key="r.id"><td><strong>{{ state.tenants.find(t => t.id === r.tenantId)?.name }}</strong></td><td>{{ dateTime(r.at) }}</td><td>{{ r.months }} 个月</td><td><span class="badge" :class="r.status === '已确认' ? 'green' : r.status === '已驳回' ? 'red' : 'amber'">{{ r.status }}</span></td><td><div v-if="r.status === '待处理'" class="row-actions"><button class="btn small primary-light" @click="approveRequest(r.id, true)">演示确认</button><button class="text-button subtle" @click="approveRequest(r.id, false)">驳回</button></div><span v-else class="muted">已处理</span></td></tr><tr v-if="!state.renewRequests.length"><td colspan="5" class="empty-cell"><Icon name="wallet" :size="32" /><strong>还没有续费申请</strong><span>进入企业演示 → 套餐与订阅 → 申请演示续费。</span><button class="btn secondary" @click="switchScreen('tenant'); navigate('billing')">前往企业订阅</button></td></tr></tbody></table><div class="roadmap-step"><span>07</span><div><strong>P2-B · 报价审批</strong><p>指定经理、异人审批、版本锁定与重新审批已实现。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>08</span><div><strong>P2-C / D · 合同与回款</strong><p>批准报价建合同、受控变更、分期收款、到账确认、冲正、更正登记与对账已接入。真实入口：合同管理 / 回款管理 / 收款对账。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>09</span><div><strong>P3 · 客户服务与系统集成</strong><p>服务工单、SLA、知识库、营销与系统集成。</p></div><span class="badge neutral">待开发</span></div><div class="roadmap-step"><span>10</span><div><strong>P4 · 行业配置、客户门户与 AI</strong><p>行业配置、客户门户与 AI 辅助。</p></div><span class="badge neutral">待开发</span></div></div></section><div class="inline-note"><Icon name="info" :size="16" />本流程没有真实收款或支付回调，确认按钮只更新演示有效期。</div>
        </template>

        <template v-else-if="view === 'audits'">
          <div class="page-heading"><div><span class="eyebrow">OPERATION HISTORY</span><h1>平台操作记录</h1><p>记录开通、套餐调整与订阅处理。企业业务操作不在此展示。</p></div></div><section class="card data-card"><div class="table-scroll"><table><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>对象</th></tr></thead><tbody><tr v-for="a in state.audits.filter(a => a.tenantId === null)" :key="a.id"><td>{{ dateTime(a.at) }}</td><td>{{ a.actor }}</td><td><span class="badge neutral">{{ a.action }}</span></td><td>{{ a.target }}</td></tr></tbody></table></div><div class="table-footer">这些是当前浏览器的演示记录；正式审计将由服务端持久保存。</div></section>
        </template>

        <template v-else-if="view === 'guide'">
          <div class="page-heading"><div><span class="eyebrow">BUILD IN VISIBLE STEPS</span><h1>版本与开发进度</h1><p>每一轮都交付可检查的结果，明确完成项与下一步。</p></div><button class="btn secondary" @click="downloadProgress"><Icon name="download" :size="16" />下载本轮记录</button></div><section class="release-hero"><div><span class="badge green">开发版本 v0.10</span><h2>合同、回款与对账已接入</h2><p>Java 与 PostgreSQL 真实服务已运行。<br>客户、商机、报价审批、合同、回款及对账统一在真实 CRM 工作台使用。</p><a class="btn primary" href="https://crm-java-api-crm-test.up.railway.app" target="_blank" rel="noopener">打开真实服务测试版</a></div><span class="release-illustration"><Icon name="layers" :size="62" /></span></section><div class="two-column"><section class="card"><div class="card-heading"><h2>本轮已经做了什么</h2></div><ul class="feature-list"><li><Icon name="check" />Vue 3 前端与响应式页面</li><li><Icon name="check" />平台运营、企业工作区与两个示例租户</li><li><Icon name="check" />客户与联系人真实接口</li><li><Icon name="check" />线索状态与原子转换真实接口</li><li><Icon name="check" />独立模块读写权限与受控数据范围</li><li><Icon name="check" />商机看板、阶段推进和成交 / 丢单历史</li><li><Icon name="check" />客户跟进、待办与完成 / 重开</li><li><Icon name="check" />事务回滚、版本与并发防重复</li><li><Icon name="check" />真实套餐、额度与人工续费</li><li><Icon name="check" />权限报表与六类 CSV 导出</li><li><Icon name="check" />客户导入预校验和批次入库</li><li><Icon name="check" />私有附件、容量与下载审计</li><li><Icon name="check" />站内提醒、任务重试和平台运维</li></ul></section><section class="card"><div class="card-heading"><h2>当前实现边界</h2></div><div class="boundary-list"><p><strong>数据</strong>全部为虚构示例，修改仅保存在当前浏览器，不跨设备同步。</p><p><strong>身份与权限</strong>前端演示身份，不是服务端认证与安全隔离。</p><p><strong>服务端</strong>独立测试版已接入登录、企业与成员管理、客户权限、联系人、线索与转换、商机历史、跟进待办、报表、CSV、附件、站内提醒、套餐续费及支持授权；本演示页面继续使用浏览器数据。</p><p><strong>外部服务</strong>没有真实支付、短信、邮件或 AI 模型调用。</p></div></section></div><section class="card"><div class="card-heading"><h2>接下来的开发顺序</h2></div><div class="roadmap"><div class="roadmap-step"><span>01</span><div><strong>P0 · 正式服务基础</strong><p>Java API、PostgreSQL 初始迁移、登录会话、企业上下文、错误协议与客户基础操作已实现，独立云测试版可体验。</p></div><span class="badge green">已建立</span></div><div class="roadmap-step"><span>02</span><div><strong>P1-A · SaaS 与权限</strong><p>真实企业开通、部门成员、客户权限、订阅额度和支持授权已实现；独立原生数据库写入验收通过。</p></div><span class="badge green">已验收</span></div><div class="roadmap-step"><span>03</span><div><strong>P1-B · 联系人与线索</strong><p>客户联系人、线索状态和原子转换已接入；87 项隔离原生库验收通过，P0 / P1-A 回归通过。</p></div><span class="badge green">已验收</span></div><div class="roadmap-step"><span>04</span><div><strong>P1-C · 商机与待办</strong><p>真实商机看板、阶段历史、成交与丢单、跟进待办及独立模块权限已接入。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>05</span><div><strong>P1-D · 试运营准备</strong><p>报表、CSV、附件、站内提醒与运维已接入；原预览每日加密备份与恢复已启用；30 天保留并保护最近 3 份。密钥离线交接、正式邮件和真实企业试点待完成。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>06</span><div><strong>P2-A · 产品与报价</strong><p>P2-A 产品目录与报价已接入真实客户企业端：明细、折扣、版本、指定经理审批、批准 / 驳回与 PDF。报价审批、合同与回款已接入；下一阶段进入自动化与集成。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>07</span><div><strong>P2-B · 报价审批</strong><p>指定经理、异人审批、版本锁定与重新审批已实现。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>08</span><div><strong>P2-C / D · 合同与回款</strong><p>批准报价建合同、受控变更、分期收款、到账确认、冲正、更正登记与对账已接入。真实入口：合同管理 / 回款管理 / 收款对账。</p></div><span class="badge green">已接入</span></div><div class="roadmap-step"><span>09</span><div><strong>P3 · 客户服务与系统集成</strong><p>服务工单、SLA、知识库、营销与系统集成。</p></div><span class="badge neutral">待开发</span></div><div class="roadmap-step"><span>10</span><div><strong>P4 · 行业配置、客户门户与 AI</strong><p>行业配置、客户门户与 AI 辅助。</p></div><span class="badge neutral">待开发</span></div></div></section><div class="inline-note"><Icon name="shield" :size="17" />线上界面预览不等于生产 SaaS 验收。后续版本以真实接口、隔离测试和业务验收为准。</div>
        </template>
        <footer class="page-footer"><span>彬彬 CRM · 企业客户经营平台</span><button @click="navigate('guide')">云端交互预览 v0.14<Icon name="arrow" :size="12" /></button></footer>
      </main>
    </div>
  </div>

  <div v-if="selectedCustomer && !dialog.type" class="drawer-overlay" @click.self="selectedCustomerId = ''">
    <aside class="detail-drawer" role="dialog" aria-modal="true" aria-labelledby="customer-detail-title"><div class="drawer-top"><span class="eyebrow">客户档案</span><button class="icon-button" aria-label="关闭客户详情" @click="selectedCustomerId = ''"><Icon name="close" /></button></div><div class="drawer-title"><span class="company-avatar large">{{ selectedCustomer.name.slice(0, 1) }}</span><div><h2 id="customer-detail-title">{{ selectedCustomer.name }}</h2><p>{{ selectedCustomer.industry }} · {{ selectedCustomer.region || '地区待补充' }}<span class="level-badge" :class="'level-' + selectedCustomer.level">{{ selectedCustomer.level }}</span></p></div></div><div class="drawer-actions"><button class="btn primary small" :disabled="readonly" @click="openDialog('activity', selectedCustomer.id)"><Icon name="plus" :size="15" />记录跟进</button><button class="btn secondary small" :disabled="readonly" @click="openDialog('editCustomer', selectedCustomer.id)">编辑</button><button v-if="manage" class="btn secondary small" :disabled="readonly" @click="openDialog('transfer', selectedCustomer.id)">转交</button><button class="btn secondary small" :disabled="readonly" @click="openDialog('share', selectedCustomer.id)">共享</button></div><div class="segment-tabs drawer-tabs"><button :class="{ active: customerTab === 'overview' }" @click="customerTab = 'overview'">概览</button><button :class="{ active: customerTab === 'activity' }" @click="customerTab = 'activity'">跟进 {{ customerActivities.length }}</button><button :class="{ active: customerTab === 'opportunities' }" @click="customerTab = 'opportunities'">商机 {{ customerOpportunities.length }}</button></div><div class="drawer-body"><template v-if="customerTab === 'overview'"><div class="detail-grid"><span>负责人<strong>{{ ownerName(selectedCustomer.ownerId) }}</strong></span><span>来源<strong>{{ selectedCustomer.source }}</strong></span><span>信用代码<strong>{{ selectedCustomer.creditCode || '待补充' }}</strong></span><span>建立时间<strong>{{ dateTime(selectedCustomer.createdAt) }}</strong></span></div><h3>客户需求</h3><p class="detail-description">{{ selectedCustomer.description || '还没有需求描述，可以编辑补充。' }}</p><h3>关键联系人</h3><div v-for="c in customerContacts" :key="c.id" class="contact-card"><span class="avatar teal">{{ initials(c.name) }}</span><div><strong>{{ c.name }} <span v-if="c.primary" class="badge green">主联系人</span></strong><p>{{ c.position }}</p><span><Icon name="phone" :size="13" />{{ D.maskPhone(c.phone, member.role) }}</span></div></div><p v-if="!customerContacts.length" class="muted">还没有联系人记录。</p><h3>客户共享</h3><p class="detail-description">{{ selectedCustomer.shares.length ? selectedCustomer.shares.map(ownerName).join('、') : '暂未共享给其他成员' }}</p></template><template v-else-if="customerTab === 'activity'"><div class="activity-timeline"><div v-for="a in customerActivities" :key="a.id" class="timeline-item"><span class="timeline-dot"></span><div><strong>{{ a.type }} · {{ ownerName(a.actorId) }}</strong><p>{{ a.content }}</p><small>{{ dateTime(a.at) }}</small></div></div><div v-if="!customerActivities.length" class="empty-state small"><Icon name="note" :size="30" /><strong>还没有跟进记录</strong><p>记录本次沟通，明确下一步。</p></div></div></template><template v-else><article v-for="o in customerOpportunities" :key="o.id" class="drawer-opportunity"><div><strong>{{ o.title }}</strong><span class="badge green">{{ o.stage }}</span></div><h3>{{ money(o.stage === '成交' ? o.actualAmount : o.amount) }}</h3><p>{{ o.nextAction || o.reason }}</p><small>预计成交 {{ o.closeDate }} · {{ ownerName(o.ownerId) }}</small><ol v-if="o.history.length" class="stage-history"><li v-for="(h, i) in o.history" :key="i"><strong>{{ h.to }}</strong><span>{{ h.reason }}</span><small>{{ dateTime(h.at) }}</small></li></ol><button v-if="!['成交', '丢单'].includes(o.stage)" class="text-button" :disabled="readonly" @click="openDialog('stage', o.id)">推进阶段<Icon name="arrow" :size="14" /></button></article><div v-if="!customerOpportunities.length" class="empty-state small"><Icon name="target" :size="32" /><strong>还没有可见商机</strong><p>客户与商机的数据权限分别判断。</p></div></template></div></aside>
  </div>

  <div v-if="dialog.type" class="modal-overlay" @click.self="closeDialog">
    <section ref="modalRef" class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-header"><div><span class="eyebrow">彬彬 CRM · 交互预览</span><h2 id="dialog-title">{{ dialogTitles[dialog.type] }}</h2></div><button class="icon-button" aria-label="关闭弹窗" @click="closeDialog"><Icon name="close" /></button></div><form @submit.prevent="saveDialog"><div class="modal-body">
      <template v-if="dialog.type === 'customer' || dialog.type === 'editCustomer'"><label>客户名称 <span>*</span><input v-model="form.name" maxlength="200" placeholder="填写企业名称" required /></label><div class="form-grid"><label>所属行业<select v-model="form.industry"><option v-for="i in ['智能装备', '精密制造', '新能源', '电子电器', '汽车零部件', '软件服务', '物业服务', '其他']" :key="i">{{ i }}</option></select></label><label>客户等级<select v-model="form.level"><option>A</option><option>B</option><option>C</option></select></label><label>来源 <span>*</span><select v-model="form.source"><option v-for="s in ['官网咨询', '展会', '客户转介绍', '主动开发', '行业活动', '其他']" :key="s">{{ s }}</option></select></label><label>地区<input v-model="form.region" placeholder="例如：深圳" /></label><label v-if="dialog.type === 'customer'">负责人 <span>*</span><select v-model="form.ownerId"><option v-for="m in owners" :key="m.id" :value="m.id">{{ m.name }}</option></select></label><label v-if="dialog.type === 'customer'">信用代码<input v-model="form.creditCode" maxlength="18" placeholder="选填，18 位" /></label></div><label>需求描述<textarea v-model="form.description" rows="3" placeholder="记录客户的业务背景和关注点"></textarea></label><template v-if="dialog.type === 'customer'"><div class="form-section-title">初始联系人 <small>选填</small></div><div class="form-grid"><label>联系人姓名<input v-model="form.contactName" placeholder="姓名" /></label><label>联系方式<input v-model="form.contactPhone" placeholder="请使用虚构号码演示" /></label></div></template></template>
      <template v-else-if="dialog.type === 'lead'"><label>线索主题 <span>*</span><input v-model="form.title" placeholder="例如：仓储条码系统改造" required /></label><label>客户企业 <span>*</span><input v-model="form.company" required /></label><div class="form-grid"><label>联系人 <span>*</span><input v-model="form.contact" required /></label><label>联系方式 <span>*</span><input v-model="form.phone" placeholder="请使用虚构号码" required /></label><label>来源<select v-model="form.source"><option v-for="s in ['官网咨询', '展会', '客户转介绍', '主动开发', '行业活动', '其他']" :key="s">{{ s }}</option></select></label><label>负责人<select v-model="form.ownerId"><option v-for="m in owners" :key="m.id" :value="m.id">{{ m.name }}</option></select></label></div><label>初步需求<textarea v-model="form.summary" rows="3"></textarea></label></template>
      <template v-else-if="dialog.type === 'opportunity'"><label>商机名称 <span>*</span><input v-model="form.title" required /></label><label>关联客户 <span>*</span><select v-model="form.customerId" required><option value="" disabled>请选择客户</option><option v-for="c in customers" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><div class="form-grid"><label>预计金额（元）<input v-model="form.amount" inputmode="decimal" required /></label><label>预计成交日期<input v-model="form.closeDate" type="date" required /></label></div><label>负责人<select v-model="form.ownerId"><option v-for="m in owners" :key="m.id" :value="m.id">{{ m.name }}</option></select></label><label>下一步 <span>*</span><textarea v-model="form.nextAction" rows="3" required></textarea></label></template>
      <template v-else-if="dialog.type === 'task'"><label>待办内容 <span>*</span><input v-model="form.title" placeholder="具体、可执行的下一步" required /></label><label>关联客户<select v-model="form.customerId"><option value="">独立待办</option><option v-for="c in customers" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><div class="form-grid"><label>截止日期<input v-model="form.dueDate" type="date" required /></label><label>优先级<select v-model="form.priority"><option>高</option><option>中</option><option>低</option></select></label></div><label>执行人<select v-model="form.assigneeId"><option v-for="m in owners" :key="m.id" :value="m.id">{{ m.name }}</option></select></label></template>
      <template v-else-if="dialog.type === 'convert'"><div class="form-callout"><Icon name="link" /><div><strong>{{ form.title }}</strong><p>{{ form.company }} · 有效线索</p></div></div><label>客户关联方式<select v-model="form.existingCustomerId"><option value="">创建新客户：{{ form.company }}</option><option v-for="c in customers" :key="c.id" :value="c.id">关联已有客户：{{ c.name }}</option></select></label><p class="form-helper">联系人将关联所选客户；再次转换不会重复创建。</p><label class="check-label"><input v-model="form.createOpportunity" type="checkbox" />同时创建商机</label><div v-if="form.createOpportunity" class="form-grid"><label>预计金额（元）<input v-model="form.amount" inputmode="decimal" required /></label><label>预计成交日期<input v-model="form.closeDate" type="date" required /></label></div></template>
      <template v-else-if="dialog.type === 'stage'"><div class="form-callout"><Icon name="target" /><strong>{{ form.title }}</strong></div><label>目标阶段<select v-model="form.stage"><option v-for="s in D.stages" :key="s">{{ s }}</option></select></label><label v-if="form.stage === '成交'">实际成交金额（元） <span>*</span><input v-model="form.actualAmount" inputmode="decimal" required /></label><label>变更说明 / 成交或丢单原因 <span>*</span><textarea v-model="form.reason" rows="3" required placeholder="记录本次变化的依据"></textarea></label><label v-if="form.stage !== '成交' && form.stage !== '丢单'">下一步 <span>*</span><textarea v-model="form.nextAction" rows="2" required></textarea></label><p class="form-helper">历史阶段和原因保留；成交金额与实收金额分别管理。</p></template>
      <template v-else-if="dialog.type === 'activity'"><label>客户<select v-model="form.customerId"><option v-for="c in customers" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>沟通方式<select v-model="form.activityType"><option>电话沟通</option><option>客户拜访</option><option>线上会议</option><option>邮件沟通</option><option>其他</option></select></label><label>沟通内容与结果 <span>*</span><textarea v-model="form.content" rows="5" required placeholder="记录确认的信息、结果和后续安排"></textarea></label></template>
      <template v-else-if="dialog.type === 'transfer'"><label>新负责人<select v-model="form.ownerId"><option v-for="m in owners" :key="m.id" :value="m.id">{{ m.name }}</option></select></label><label>转交原因 <span>*</span><textarea v-model="form.reason" rows="3" required></textarea></label><p class="form-helper">本操作转交客户；已有商机和待办保持各自负责人。</p></template>
      <template v-else-if="dialog.type === 'share'"><label>协作成员<select v-model="form.memberId"><option v-for="m in members.filter(m => m.id !== form.ownerId)" :key="m.id" :value="m.id">{{ m.name }}{{ customers.find(c => c.id === dialog.id)?.shares.includes(m.id) ? ' · 已共享' : '' }}</option></select></label><p class="form-helper">选择已共享成员会取消共享；共享客户不会自动共享该客户的全部商机。</p></template>
      <template v-else-if="dialog.type === 'member'"><div class="form-grid"><label>姓名 <span>*</span><input v-model="form.name" required /></label><label>邮箱 <span>*</span><input v-model="form.email" type="email" placeholder="demo@example.test" required /></label><label>部门<input v-model="form.department" /></label><label>角色<select v-model="form.role"><option v-for="(label, role) in D.roleLabels" :key="role" :value="role">{{ label }}</option></select></label></div><div class="form-callout"><Icon name="info" /><p>仅创建演示成员，不发送邀请，不建立正式登录凭证。</p></div></template>
      <template v-else-if="dialog.type === 'tenant'"><label>企业名称 <span>*</span><input v-model="form.name" required /></label><div class="form-grid"><label>所属行业<input v-model="form.industry" /></label><label>演示管理员 <span>*</span><input v-model="form.adminName" required /></label></div><label>套餐<select v-model="form.planId"><option v-for="p in state.plans" :key="p.id" :value="p.id">{{ p.name }} · {{ money(p.price) }}/月（演示）</option></select></label><p class="form-helper">新企业使用 1 个月演示有效期，不产生真实收费。</p></template>
      <template v-else-if="dialog.type === 'renew' || dialog.type === 'requestRenew'"><div class="form-callout"><Icon name="wallet" /><strong>{{ dialog.type === 'renew' ? state.tenants.find(t => t.id === dialog.id)?.name : tenant.name }}</strong></div><label>续费周期<select v-model="form.months"><option :value="1">1 个月</option><option :value="3">3 个月</option><option :value="6">6 个月</option><option :value="12">12 个月</option></select></label><p class="form-helper">{{ dialog.type === 'renew' ? '本操作演示确认续费并延长有效期，没有真实收款。' : '提交后可切换平台演示后台处理，不产生支付。' }}</p></template>
      <template v-else-if="dialog.type === 'plan'"><label>套餐名称<input v-model="form.name" required /></label><div class="form-grid"><label>月度示例价格（元）<input v-model="form.price" inputmode="decimal" required /></label><label>成员名额<input v-model.number="form.seats" type="number" min="1" required /></label><label>客户数量上限<input v-model.number="form.customerLimit" type="number" min="1" required /></label><label>附件容量（GB）<input v-model.number="form.storageGB" type="number" min="1" required /></label></div><p class="form-helper">仅修改演示套餐；额度不能低于当前使用数量。</p></template>
      <template v-else-if="dialog.type === 'reset'"><div class="reset-illustration"><Icon name="refresh" :size="36" /></div><h3>恢复两个初始示例企业</h3><p class="detail-description">本浏览器中新增或修改的演示客户、商机、待办、成员、企业和订阅将清除，恢复初始示例。不会影响其他设备。</p></template>
      <div v-if="dialog.error" class="form-error" role="alert"><Icon name="info" :size="16" />{{ dialog.error }}</div>
    </div><div class="modal-footer"><button type="button" class="btn secondary" @click="closeDialog">取消</button><button type="submit" class="btn primary">{{ dialog.type === 'convert' ? '确认转换' : dialog.type === 'reset' ? '确认恢复' : dialog.type === 'requestRenew' ? '提交演示申请' : '保存演示修改' }}<Icon name="check" :size="16" /></button></div></form></section>
  </div>
  <Transition name="toast"><div v-if="toast.text" class="toast-message" :class="toast.kind" role="status" aria-live="polite"><span class="toast-icon"><Icon :name="toast.kind === 'error' ? 'info' : 'check'" :size="17" /></span>{{ toast.text }}<button aria-label="关闭提示" @click="toast.text = ''"><Icon name="close" :size="16" /></button></div></Transition>
</template>
